import * as React from "react";
import { createPopper } from "@popperjs/core";
import type { Instance, Options, Placement } from "@popperjs/core";
import "./Popper.scss";

export interface PopperProps {
  /**
   * Unique identifier of content instance, used for querying content element.
   */
  id: string;
  /**
   * Anchor element used to position the popper
   */
  anchorEl: HTMLElement;
  /**
   * Content to be displayed within the popper
   */
  children: React.ReactNode;
  /**
   * Popper.JS placement options.
   */
  placement?: Placement;
  /**
   * Popper.JS options.
   */
  popperProps?: Options;
}

const Popper = ({
  id,
  anchorEl,
  children,
  placement = "bottom",
  popperProps,
}: PopperProps) => {
  React.useEffect(() => {
    let popperInstance: Instance | null;
    if (anchorEl) {
      const element = document.querySelector(`#${id}`);
      popperInstance = createPopper(anchorEl, element as HTMLElement, {
        placement,
        ...popperProps,
      });
    }

    return () => {
      if (popperInstance) {
        popperInstance.destroy();
      }
    };
  }, [anchorEl]);

  return anchorEl ? <div className="popper-container">{children}</div> : null;
};

export default Popper;
